import { useEffect, useState, useRef, useCallback } from "react";

const DIRECTIONS = ["NORTH", "SOUTH", "EAST", "WEST"];
const API = "http://localhost:5000";
const WS_URL = "ws://localhost:5000";

// ── Preset destinations for prototype ──────────────────────────────────────────
const PRESET_DESTINATIONS = [
  { name: "Government Hospital", latitude: 12.9822, longitude: 77.6194 },
  { name: "City Medical Center", latitude: 12.9785, longitude: 77.6124 },
  { name: "Apollo Hospital", latitude: 12.9758, longitude: 77.6193 },
  { name: "Emergency Care Unit", latitude: 12.9800, longitude: 77.6150 },
];

// ── Helper utilities ───────────────────────────────────────────────────────────
function api(path, method = "GET", body = null) {
  const opts = { method, headers: { "Content-Type": "application/json" } };
  if (body) opts.body = JSON.stringify(body);
  return fetch(`${API}${path}`, opts).then((r) => r.json());
}

function densityColor(density) {
  if (density === "HIGH")   return "var(--danger)";
  if (density === "MEDIUM") return "var(--warn)";
  if (density === "LOW")    return "var(--success)";
  return "var(--muted)";
}

function signalColor(sig) {
  if (sig === "GREEN")  return "var(--success)";
  if (sig === "RED")    return "var(--danger)";
  if (sig === "YELLOW") return "var(--warn)";
  return "var(--muted)";
}

function priorityColor(status) {
  if (status === "ACTIVE")    return "var(--danger)";
  if (status === "PREPARING") return "var(--warn)";
  return "var(--muted)";
}

// ── Sub-components ─────────────────────────────────────────────────────────────

function StatusPill({ value, onColor = "success", offColor = "muted", label }) {
  const map = { success: "var(--success)", danger: "var(--danger)", warn: "var(--warn)", muted: "var(--muted)", accent: "var(--accent)" };
  const isOn = value === true || value === "ACTIVE" || value === "LIVE" || value === "CONNECTED" || value === "ONLINE";
  const color = map[isOn ? onColor : offColor] || "var(--muted)";
  return (
    <span className="status-pill" style={{ background: `${color}22`, color, border: `1px solid ${color}44` }}>
      {label || (isOn ? "●" : "○")} {value}
    </span>
  );
}

function InfoRow({ label, value, valueColor }) {
  return (
    <div className="info-row">
      <span>{label}</span>
      <strong style={valueColor ? { color: valueColor } : {}}>{value ?? "--"}</strong>
    </div>
  );
}

function SignalLight({ direction, state: sig }) {
  const color = signalColor(sig);
  return (
    <div className="signal-light-box">
      <div className="signal-dir-label">{direction}</div>
      <div className="signal-bulb-stack">
        <div className="signal-bulb" style={{ background: sig === "RED" ? "#ef4444" : "#ef444433" }} />
        <div className="signal-bulb" style={{ background: sig === "YELLOW" ? "#fbbf24" : "#fbbf2433" }} />
        <div className="signal-bulb" style={{ background: sig === "GREEN" ? "#22c55e" : "#22c55e33" }} />
      </div>
      <div className="signal-state-label" style={{ color }}>{sig || "OFF"}</div>
    </div>
  );
}

// ── Main App ───────────────────────────────────────────────────────────────────
export default function App() {
  const [appState, setAppState] = useState(null);
  const [wsStatus, setWsStatus] = useState("CONNECTING");
  const [screen, setScreen] = useState("PRETRIP"); // PRETRIP | DASHBOARD
  const [destination, setDestination] = useState(null);
  const [destSearch, setDestSearch] = useState("");
  const [destDropdown, setDestDropdown] = useState(false);
  const [gpsStatus, setGpsStatus] = useState("OFFLINE"); // OFFLINE | WAITING | LIVE | DENIED
  const [gpsWatcher, setGpsWatcher] = useState(null);
  const [activeTab, setActiveTab] = useState("overview"); // overview | log | manual
  const logRef = useRef(null);
  const wsRef = useRef(null);

  // ── WebSocket connection ───────────────────────────────────────────────────
  const connectWs = useCallback(() => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) return;

    const ws = new window.WebSocket(WS_URL);
    wsRef.current = ws;
    setWsStatus("CONNECTING");

    ws.onopen = () => setWsStatus("CONNECTED");
    ws.onmessage = (evt) => {
      try {
        const msg = JSON.parse(evt.data);
        if (msg.type === "state") setAppState(msg.data);
      } catch (_) {}
    };
    ws.onclose = () => {
      setWsStatus("DISCONNECTED");
      setTimeout(connectWs, 3000);
    };
    ws.onerror = () => {
      setWsStatus("ERROR");
      ws.close();
    };
  }, []);

  useEffect(() => {
    connectWs();
    return () => {
      if (wsRef.current) wsRef.current.close();
    };
  }, [connectWs]);

  // Auto-scroll event log
  useEffect(() => {
    if (logRef.current) {
      logRef.current.scrollTop = logRef.current.scrollHeight;
    }
  }, [appState?.eventLog?.length]);

  // ── GPS Tracking ───────────────────────────────────────────────────────────
  const startGps = useCallback(() => {
    if (!navigator.geolocation) {
      setGpsStatus("DENIED");
      api("/api/emergency/location", "POST", { gpsStatus: "DENIED" });
      return;
    }
    setGpsStatus("WAITING");
    api("/api/emergency/location", "POST", { gpsStatus: "WAITING" });

    const watchId = navigator.geolocation.watchPosition(
      (pos) => {
        setGpsStatus("LIVE");
        api("/api/emergency/location", "POST", {
          latitude: pos.coords.latitude,
          longitude: pos.coords.longitude,
          speed: pos.coords.speed,
          heading: pos.coords.heading,
          accuracy: pos.coords.accuracy,
          gpsStatus: "LIVE",
        });
      },
      (err) => {
        const status = err.code === 1 ? "DENIED" : "ERROR";
        setGpsStatus(status);
        api("/api/emergency/location", "POST", { gpsStatus: status });
      },
      { enableHighAccuracy: true, maximumAge: 3000, timeout: 10000 }
    );
    setGpsWatcher(watchId);
  }, []);

  const stopGps = useCallback(() => {
    if (gpsWatcher !== null) {
      navigator.geolocation.clearWatch(gpsWatcher);
      setGpsWatcher(null);
    }
    setGpsStatus("OFFLINE");
  }, [gpsWatcher]);

  // ── Start Emergency ────────────────────────────────────────────────────────
  const handleStartEmergency = async () => {
    if (!destination) return;
    // 1. Set destination on backend
    await api("/api/emergency/destination", "POST", destination);
    // 2. Start emergency mode
    await api("/api/emergency/start", "POST", {});
    // 3. Request GPS
    startGps();
    // 4. Switch to dashboard
    setScreen("DASHBOARD");
  };

  // ── Stop Emergency ────────────────────────────────────────────────────────
  const handleStopEmergency = async () => {
    stopGps();
    await api("/api/emergency/stop", "POST", {});
    setScreen("PRETRIP");
    setDestination(null);
    setDestSearch("");
  };

  // ── Manual Signal ─────────────────────────────────────────────────────────
  const sendManualSignal = (dir) =>
    api("/api/signal/test", "POST", { direction: dir });

  const sendNormalMode = () => api("/api/signal/normal", "POST", {});

  // ── Destination Filter ─────────────────────────────────────────────────────
  const filteredDests = destSearch.length > 0
    ? PRESET_DESTINATIONS.filter((d) =>
        d.name.toLowerCase().includes(destSearch.toLowerCase())
      )
    : PRESET_DESTINATIONS;

  const s = appState || {};
  const vehicle = s.vehicle || {};
  const traffic = s.trafficData || {};
  const signalState = s.signalState || { NORTH: "RED", SOUTH: "RED", EAST: "RED", WEST: "RED" };
  const esp32 = s.esp32 || {};
  const route = s.route || {};
  const routeCandidates = s.routeCandidates || [];
  const nextIntersection = s.nextIntersection || null;
  const distanceM = s.distanceToIntersectionM;
  const priorityStatus = s.intersectionPriorityStatus || "INACTIVE";
  const eventLog = s.eventLog || [];
  const serialLog = s.serialLog || [];

  // ── PRE-TRIP SCREEN ────────────────────────────────────────────────────────
  if (screen === "PRETRIP") {
    return (
      <div className="app-shell">
        <header className="topbar">
          <div>
            <p className="eyebrow">Smart Traffic Management System</p>
            <h1>Emergency Vehicle Priority</h1>
          </div>
          <div className="ws-badge">
            <span className={`ws-dot ${wsStatus === "CONNECTED" ? "ws-ok" : "ws-err"}`} />
            Backend {wsStatus}
          </div>
        </header>

        <div className="pretrip-shell">
          <div className="pretrip-card">
            <div className="pretrip-badge">🚑 EMERGENCY VEHICLE</div>
            <h2 className="pretrip-title">Start Emergency Trip</h2>

            <div className="pretrip-vehicle-row">
              <span className="pretrip-label">Vehicle</span>
              <strong className="pretrip-vehicle-name">Ambulance 01</strong>
            </div>

            <div className="pretrip-section">
              <label className="pretrip-label">Destination</label>
              <div className="dest-search-wrap">
                <input
                  id="dest-search"
                  className="dest-input"
                  placeholder="Search destination..."
                  value={destSearch}
                  onChange={(e) => { setDestSearch(e.target.value); setDestDropdown(true); setDestination(null); }}
                  onFocus={() => setDestDropdown(true)}
                  autoComplete="off"
                />
                {destination && (
                  <div className="dest-selected-badge">
                    📍 {destination.name}
                  </div>
                )}
                {destDropdown && (
                  <ul className="dest-dropdown">
                    {filteredDests.map((d) => (
                      <li
                        key={d.name}
                        className="dest-option"
                        onClick={() => {
                          setDestination(d);
                          setDestSearch(d.name);
                          setDestDropdown(false);
                        }}
                      >
                        <span className="dest-icon">📍</span>
                        <div>
                          <div className="dest-name">{d.name}</div>
                          <div className="dest-coords">{d.latitude.toFixed(4)}, {d.longitude.toFixed(4)}</div>
                        </div>
                      </li>
                    ))}
                    {filteredDests.length === 0 && (
                      <li className="dest-option dest-noresult">No results found</li>
                    )}
                  </ul>
                )}
              </div>
            </div>

            <button
              id="start-emergency-btn"
              className={`start-emergency-btn ${destination ? "ready" : "disabled"}`}
              onClick={handleStartEmergency}
              disabled={!destination}
            >
              {destination ? "🚨 START EMERGENCY" : "Select a destination first"}
            </button>

            <div className="pretrip-note">
              GPS tracking and emergency signal control will begin after you press START EMERGENCY.
            </div>
          </div>

          {/* Live system status even on pre-trip */}
          <div className="pretrip-status-row">
            <div className="pretrip-status-chip">
              <span className={`status-dot ${traffic.cameraStatus === "CONNECTED" ? "dot-ok" : "dot-err"}`} />
              Camera: {traffic.cameraStatus || "DISCONNECTED"}
            </div>
            <div className="pretrip-status-chip">
              <span className={`status-dot ${traffic.modelStatus === "ACTIVE" || traffic.modelStatus === "READY" ? "dot-ok" : "dot-warn"}`} />
              AI Model: {traffic.modelStatus || "LOADING"}
            </div>
            <div className="pretrip-status-chip">
              <span className={`status-dot ${esp32.connected ? "dot-ok" : "dot-err"}`} />
              ESP32: {esp32.status || "DISCONNECTED"}
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ── MAIN DASHBOARD ────────────────────────────────────────────────────────
  return (
    <div className="app-shell">
      {/* ── Header ── */}
      <header className="topbar">
        <div>
          <p className="eyebrow">Smart Traffic Management System</p>
          <h1>Emergency Vehicle Priority</h1>
        </div>
        <div className="topbar-right">
          <div className="mode-badge" style={{
            background: s.emergencyMode ? "rgba(239,68,68,0.18)" : "rgba(34,197,94,0.12)",
            color: s.emergencyMode ? "var(--danger)" : "var(--success)",
            border: `1px solid ${s.emergencyMode ? "#ef444466" : "#22c55e44"}`,
          }}>
            {s.emergencyMode ? "🚨 EMERGENCY MODE" : "✅ NORMAL MODE"}
          </div>
          <div className="ws-badge">
            <span className={`ws-dot ${wsStatus === "CONNECTED" ? "ws-ok" : "ws-err"}`} />
            {wsStatus}
          </div>
          <button className="stop-btn" onClick={handleStopEmergency} id="stop-emergency-btn">
            ✕ End Trip
          </button>
        </div>
      </header>

      {/* ── Tab Bar ── */}
      <div className="tab-bar">
        {[["overview", "📊 Overview"], ["log", "📋 Event Log"], ["manual", "🔧 Manual Test"]].map(([id, label]) => (
          <button
            key={id}
            id={`tab-${id}`}
            className={`tab-btn ${activeTab === id ? "tab-active" : ""}`}
            onClick={() => setActiveTab(id)}
          >
            {label}
          </button>
        ))}
      </div>

      {/* ═══ OVERVIEW TAB ═══ */}
      {activeTab === "overview" && (
        <>
          {/* ── Top row ── */}
          <div className="dash-row-top">

            {/* Emergency Vehicle */}
            <div className="card">
              <div className="card-head">
                <h2>🚑 Emergency Vehicle</h2>
                <StatusPill value={vehicle.status} onColor="danger" label="" />
              </div>
              <InfoRow label="Vehicle" value={vehicle.name} />
              <InfoRow label="Status" value={vehicle.status} valueColor={vehicle.status === "ACTIVE" ? "var(--danger)" : "var(--muted)"} />
              <div className="info-row">
                <span>GPS</span>
                <span className="gps-live-badge" style={{
                  color: gpsStatus === "LIVE" ? "var(--success)" : gpsStatus === "WAITING" ? "var(--warn)" : "var(--danger)",
                }}>
                  {gpsStatus === "LIVE" ? "● LIVE" : gpsStatus === "WAITING" ? "◌ WAITING..." : gpsStatus === "DENIED" ? "✕ DENIED" : "○ OFFLINE"}
                </span>
              </div>
              <InfoRow
                label="Location"
                value={vehicle.latitude ? `${vehicle.latitude.toFixed(5)}, ${vehicle.longitude.toFixed(5)}` : "Waiting for GPS..."}
              />
              <InfoRow label="Speed" value={vehicle.speedKmh !== undefined ? `${vehicle.speedKmh} km/h` : "--"} />
              <InfoRow label="Heading" value={vehicle.heading || "--"} />
              <InfoRow label="Destination" value={s.destination?.name || "--"} />
              <InfoRow label="ETA" value={vehicle.etaMinutes !== undefined ? `${vehicle.etaMinutes} min` : "--"} />
              <InfoRow label="Distance" value={vehicle.distanceKm !== undefined ? `${vehicle.distanceKm} km` : "--"} />
            </div>

            {/* Traffic AI */}
            <div className="card">
              <div className="card-head">
                <h2>🤖 Traffic AI</h2>
                <StatusPill value={traffic.modelStatus === "ACTIVE" ? "ACTIVE" : traffic.modelStatus} onColor="accent" label="" />
              </div>
              <InfoRow label="Camera" value={traffic.cameraStatus || "DISCONNECTED"} valueColor={traffic.cameraStatus === "CONNECTED" ? "var(--success)" : "var(--danger)"} />
              <InfoRow label="Model" value="best.onnx" />
              <InfoRow label="Status" value={traffic.modelStatus || "LOADING"} valueColor={traffic.modelStatus === "ACTIVE" ? "var(--success)" : traffic.modelStatus === "FALLBACK" ? "var(--warn)" : "var(--muted)"} />
              <InfoRow label="Vehicle Count" value={traffic.vehicleCount ?? "--"} />
              <InfoRow label="Overall Density" value={traffic.trafficDensity || "--"} valueColor={densityColor(traffic.trafficDensity)} />
              <InfoRow
                label="Last Inference"
                value={traffic.lastInferenceAge !== null && traffic.lastInferenceAge !== undefined
                  ? `${traffic.lastInferenceAge}s ago`
                  : "Never"}
              />

              <div className="lane-density-grid">
                {DIRECTIONS.map((dir) => {
                  const lane = traffic[dir.toLowerCase()] || {};
                  return (
                    <div key={dir} className="lane-chip" style={{ borderColor: `${densityColor(lane.trafficDensity)}44` }}>
                      <div className="lane-dir">{dir}</div>
                      <div className="lane-count">{lane.vehicleCount ?? 0}</div>
                      <div className="lane-density" style={{ color: densityColor(lane.trafficDensity) }}>
                        {lane.trafficDensity || "—"}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Signal Status */}
            <div className="card">
              <div className="card-head">
                <h2>🚦 Traffic Signal</h2>
                <span className="mode-chip" style={{
                  color: s.trafficMode === "EMERGENCY" ? "var(--danger)" : "var(--success)",
                }}>
                  {s.trafficMode === "EMERGENCY" ? "EMERGENCY" : "NORMAL"}
                </span>
              </div>
              <div className="signals-row">
                {DIRECTIONS.map((dir) => (
                  <SignalLight key={dir} direction={dir} state={signalState[dir]} />
                ))}
              </div>
            </div>
          </div>

          {/* ── Bottom row ── */}
          <div className="dash-row-bottom">

            {/* Upcoming Intersection */}
            <div className="card">
              <div className="card-head">
                <h2>🔀 Upcoming Intersection</h2>
                <span className="priority-badge" style={{
                  color: priorityColor(priorityStatus),
                  background: `${priorityColor(priorityStatus)}22`,
                  border: `1px solid ${priorityColor(priorityStatus)}44`,
                }}>
                  {priorityStatus}
                </span>
              </div>
              {nextIntersection ? (
                <>
                  <InfoRow label="ID" value={nextIntersection.id} />
                  <InfoRow label="Name" value={nextIntersection.name} />
                  <InfoRow
                    label="Distance"
                    value={distanceM !== null ? `${distanceM} m` : "--"}
                    valueColor={
                      distanceM <= PRIORITY_ACTIVATE_DISTANCE_M ? "var(--danger)"
                        : distanceM <= PRIORITY_PREPARE_DISTANCE_M ? "var(--warn)"
                        : "var(--text)"
                    }
                  />
                  <InfoRow label="Direction" value={s.intersectionDirection || "--"} />
                  <div className="priority-distance-bar">
                    <div className="pd-label">Priority zones</div>
                    <div className="pd-track">
                      <div className="pd-zone pd-safe">Safe &gt;500m</div>
                      <div className="pd-zone pd-prepare">Prepare 300-500m</div>
                      <div className="pd-zone pd-active">Active ≤300m</div>
                    </div>
                    {distanceM !== null && (
                      <div className="pd-marker-row">
                        <div className="pd-marker-label">Current: {distanceM}m</div>
                      </div>
                    )}
                  </div>
                </>
              ) : (
                <div className="no-intersection">
                  {s.emergencyMode ? "Calculating next intersection..." : "Start emergency to detect intersections"}
                </div>
              )}
            </div>

            {/* Route Details */}
            <div className="card">
              <div className="card-head">
                <h2>🗺️ Route Selection</h2>
              </div>
              {routeCandidates.length > 0 ? (
                <div className="route-table-wrap">
                  <table className="route-table">
                    <thead>
                      <tr>
                        <th>Route</th>
                        <th>Dist</th>
                        <th>Traffic</th>
                        <th>ETA</th>
                      </tr>
                    </thead>
                    <tbody>
                      {routeCandidates.map((r) => (
                        <tr
                          key={r.id}
                          className={r.id === route.id ? "route-selected" : ""}
                        >
                          <td>
                            {r.id === route.id ? <span className="route-star">★</span> : ""} {r.id}
                          </td>
                          <td>{r.distanceKm} km</td>
                          <td style={{ color: densityColor(r.traffic) }}>{r.traffic}</td>
                          <td>{r.etaMinutes} min</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {s.routeRecommendation && (
                    <p className="route-recommendation">{s.routeRecommendation}</p>
                  )}
                </div>
              ) : (
                <div className="no-intersection">Loading routes...</div>
              )}
            </div>

            {/* ESP32 Status */}
            <div className="card">
              <div className="card-head">
                <h2>⚡ ESP32</h2>
                <StatusPill value={esp32.connected ? "CONNECTED" : "DISCONNECTED"} onColor="success" offColor="danger" label="" />
              </div>
              <InfoRow label="Connection" value={esp32.connected ? "CONNECTED" : "DISCONNECTED"} valueColor={esp32.connected ? "var(--success)" : "var(--danger)"} />
              <InfoRow label="Serial Port" value={esp32.port || "COM3"} />
              <InfoRow label="Baud Rate" value={esp32.baudRate || 115200} />
              <InfoRow label="Status" value={esp32.status || "DISCONNECTED"} />
              <InfoRow label="Last Command" value={esp32.lastCommand || "NONE"} />
              <InfoRow label="Last Response" value={esp32.lastResponse || "NONE"} />

              <div className="serial-mini">
                {serialLog.slice(-6).map((entry, i) => (
                  <div key={i} className="serial-mini-line">
                    <span className="serial-dir">{entry.direction}</span>
                    <span className="serial-ts">{entry.timestamp}</span>
                    <span className="serial-payload">{entry.payload}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </>
      )}

      {/* ═══ EVENT LOG TAB ═══ */}
      {activeTab === "log" && (
        <div className="card log-card">
          <div className="card-head">
            <h2>📋 Live System Event Log</h2>
            <span className="log-count">{eventLog.length} events</span>
          </div>
          <div className="event-log-scroll" ref={logRef}>
            {eventLog.length === 0 ? (
              <div className="log-empty">No events yet. Start the system to see live events.</div>
            ) : (
              [...eventLog].reverse().map((entry, i) => (
                <div key={i} className="log-entry">
                  <span className="log-ts">{entry.timestamp}</span>
                  <span className="log-msg">{entry.message}</span>
                </div>
              ))
            )}
          </div>

          <div className="card-head" style={{ marginTop: "18px" }}>
            <h2>📡 Serial Monitor</h2>
          </div>
          <div className="serial-log-scroll">
            {serialLog.length === 0 ? (
              <div className="log-empty">No serial communication yet.</div>
            ) : (
              [...serialLog].reverse().map((entry, i) => (
                <div key={i} className="serial-log-entry">
                  <span className="serial-dir-badge" style={{
                    color: entry.direction === "→" ? "var(--accent)" : "var(--warn)",
                  }}>
                    {entry.direction}
                  </span>
                  <span className="serial-ts">{entry.timestamp}</span>
                  <span className="serial-payload">{entry.payload}</span>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* ═══ MANUAL TEST TAB ═══ */}
      {activeTab === "manual" && (
        <div className="card manual-card">
          <div className="card-head">
            <h2>🔧 Manual Test Mode</h2>
            <span className="manual-note">For debugging/demonstration only — not connected to emergency logic</span>
          </div>

          <p className="manual-desc">
            Click a direction button to send the corresponding GREEN signal command directly to the ESP32 via USB Serial.
            This bypasses automatic emergency and normal mode logic.
          </p>

          <div className="manual-grid">
            {DIRECTIONS.map((dir) => (
              <button
                key={dir}
                id={`manual-${dir.toLowerCase()}`}
                className="manual-signal-btn"
                onClick={() => sendManualSignal(dir)}
              >
                🟢 {dir} GREEN
              </button>
            ))}
            <button
              id="manual-normal"
              className="manual-normal-btn"
              onClick={sendNormalMode}
            >
              ↺ NORMAL MODE
            </button>
          </div>

          <div className="manual-serial-preview">
            <div className="card-head" style={{ marginBottom: "10px" }}>
              <h3>Recent Commands</h3>
            </div>
            {serialLog.length === 0 ? (
              <div className="log-empty">No commands sent yet.</div>
            ) : (
              serialLog.slice(-10).reverse().map((entry, i) => (
                <div key={i} className="serial-log-entry">
                  <span className="serial-dir-badge" style={{
                    color: entry.direction === "→" ? "var(--accent)" : "var(--warn)",
                  }}>
                    {entry.direction}
                  </span>
                  <span className="serial-ts">{entry.timestamp}</span>
                  <span className="serial-payload">{entry.payload}</span>
                </div>
              ))
            )}
          </div>

          {/* Signal state preview */}
          <div className="card-head" style={{ marginTop: "20px" }}>
            <h3>Current Signal State</h3>
          </div>
          <div className="signals-row">
            {DIRECTIONS.map((dir) => (
              <SignalLight key={dir} direction={dir} state={signalState[dir]} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
